  png_ptr->next_in = buffer;
  png_ptr->avail_in = static_cast<uint32_t>(buffer_length);
  while (png_ptr->avail_in > 0 && !(png_ptr->flags & PNG_FLAG_ZSTREAM_ENDED)) {
    png_ptr->last_byte ^= *png_ptr->next_in++;
    png_ptr->avail_in--;
    png_push_process_row(png_ptr);
  }
}

