  const std::vector<SubGraph>* subgraphs_;
  const std::vector<SubGraph>* subgraphs() const { return subgraphs_; }
};

int BuildInterpreter(const Model* model, int* out_subgraph_count) {
  auto* subgraphs = model->subgraphs();
